export type ScanType = 'MRI' | 'CT' | 'X-ray';
export type ScanOrientation = 'Axial' | 'Coronal' | 'Sagittal' | 'Not specified';
export type TaskStatus = 'ready' | 'setup_required' | 'coming_later';

export interface TaskSetupGuide {
  recommended_datasets: string[];
  required_sequences: string[];
  split_policy: string;
  target_classes: string[];
  expected_model_path: string;
  expected_dataset_dir: string;
  data_leakage_risks: string[];
  setup_steps: string[];
}

export interface TaskInfo {
  task_id: string;
  name: string;
  short_title: string;
  category: string;
  status: TaskStatus;
  tagline: string;
  description: string;
  supported_scan_types: string[];
  required_sequences: string[];
  supported_orientations: string[];
  supported_formats: string[];
  class_labels: string[];
  model_loaded: boolean;
  model_name?: string | null;
  model_version?: string | null;
  input_shape?: number[] | null;
  trainable_parameters?: number | null;
  evaluation_available: boolean;
  overall_accuracy?: number | null;
  limitations: string[];
  disclaimer: string;
  setup_guide?: TaskSetupGuide | null;
}

export interface ClassScore {
  class_name: string;
  score: number;
  percentage: number;
}

export interface PredictionResponse {
  task_id?: string;
  task_name?: string;
  predicted_category: string;
  model_score: number;
  score_label: string;
  per_class_scores: ClassScore[];
  filename: string;
  scan_type: string;
  orientation_label: string;
  model_name: string;
  model_version: string;
  gradcam_available: boolean;
  gradcam_image_base64: string | null;
  gradcam_explanation: string | null;
  uncertainty_notice: string | null;
  disclaimer: string;
}

export interface HealthResponse {
  status: string;
  api_version: string;
  model_loaded: boolean;
  model_name: string | null;
  supported_scan_types: string[];
  disabled_scan_types: string[];
  supported_image_formats: string[];
  max_upload_size_mb: number;
  disclaimer: string;
  active_tasks_count?: number;
  total_tasks_count?: number;
}

export interface ModelInfoResponse {
  loaded: boolean;
  model_name: string | null;
  model_version: string | null;
  input_shape: number[] | null;
  supported_classes: string[];
  supported_scan_type: string;
  training_status: string;
  evaluation_available: boolean;
  architecture_summary: string | null;
  layer_count: number | null;
  trainable_parameters: number | null;
  trained_at: string | null;
  disclaimer: string;
}

export interface EvaluationResponse {
  evaluated: boolean;
  model_name?: string;
  model_version?: string;
  evaluated_at?: string;
  dataset_split?: string;
  test_images_count?: number;
  overall_accuracy?: number;
  per_class_metrics?: Record<string, {
    precision: number;
    recall: number;
    f1_score: number;
    support: number;
  }>;
  confusion_matrix?: {
    matrix: number[][];
    classes: string[];
  };
  training_history?: Record<string, number[]>;
  metric_interpretations?: Record<string, string>;
  disclaimer: string;
}

export interface DatasetInfoResponse {
  available: boolean;
  dataset_name: string;
  source: string;
  license_terms?: string;
  folder_layout?: string;
  class_distribution: Record<string, number>;
  split_counts: Record<string, number>;
  total_images: number;
  input_resolution?: string;
  color_mode?: string;
  normalization?: string;
  disclaimer: string;
  task_id?: string;
  setup_guide?: TaskSetupGuide;
}

export interface ScanGalleryItem {
  id: string;
  file: File;
  previewUrl: string;
  name: string;
  size: number;
  orientation: ScanOrientation;
  scanType: ScanType;
}

export interface SessionHistoryItem {
  id: string;
  timestamp: string;
  filename: string;
  previewUrl: string;
  prediction: PredictionResponse;
}

export interface SampleScan {
  id: string;
  category: string;
  title: string;
  description: string;
  filename: string;
  orientation: ScanOrientation;
  scan_type: ScanType;
  static_url: string;
}
